-- Generated by scripts/fll_parts_sql.py from site/data/parts-catalog.json. Do not edit by hand.
-- 133 LEGO parts for FLL teams (SPIKE, EV3, Technic, season sets). Safe to re-run.
on conflict (name, coalesce(brand, '')) do update set
  sku = excluded.sku, category = excluded.category, program = excluded.program;
